def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>Finding direction, time and distance without GPS comes down to a few instruments: the sundial, the magnetic compass, the surveyor's pocket transit, the odometer, the chronometer and finally the gyrocompass. These patent drawings show how each is built, from a sundial and floating-card compass anyone can make, through instrument-shop transits and gimballed cases, to precision timekeeping and gyro machinery. Use them with the compass, sun-and-star and map chapters of this guide.</p>"
UNPATENTED = ["The shadow-stick method of finding north, steering by the North Star, and floating a magnetised needle on water as a compass are old knowledge and free to use."]
PATENTS = [
P("US6506","37/f6/11/627df7531f902f/US6506.pdf","f0/cb/c6/df82ad54720723/US6506-drawings-page-1.png","A","1849-06-05","James Scott (Portland, Maine)","Sun-dial",
  "A sundial whose gnomon is carried on an upright plate marked with a scale of the sun's declination (day of the month), so the dial can be corrected through the year. It shows the parts of an accurate dial that can be built from wood or sheet metal.","Fig. 1 top view; Fig. 2 side elevation; Fig. 3 centre bar; Fig. 4 declination plate"),
P("US35156","b8/d4/49/b81568bedf6371/US35156.pdf","pdf:1","A","1862-05-06","H. W. Hunter","Improvement in magnetic compasses",
  "A compass with a floating card painted in strongly contrasting halves, so north can be read at a glance, even in poor light. It is a simple improvement for a home-made needle-and-card compass.","Fig. 1 compass and floating card; Fig. 2 plan of the card"),
P("US166137","cb/c7/e6/693b3b7bbfdf79/US166137.pdf","03/70/21/1d36125b4dacbb/US166137-drawings-page-1.png","B","1875-07-27","Harrison C. Pearsons","Improvement in apparatus for finding true meridian",
  "A solar instrument for finding true north, the magnetic declination (the difference between true and compass north) and local sun time, used alone or fitted to a surveying or ship's instrument.","Instrument elevation, sight and graduated arcs"),
P("US526021","fc/af/18/62124a2b0ea2ca/US526021.pdf","14/75/38/a01c32e50ffc12/US526021-drawings-page-1.png","B","1894-09-18","David W. Brunton (Aspen, Colorado)","Pocket-transit (the Brunton compass)",
  "The Brunton pocket transit: a folding compass with sights, a mirror, a bubble level and a clinometer arm, so a surveyor can take a bearing and read the needle while sighting above or below the horizontal. It is still the standard field geologist's compass.","Plan and section of the case, needle, sights, mirror and level arm"),
P("US712869","9f/bf/d4/f69ec11cf72f38/US712869.pdf","0a/b8/43/ab196ebdd58912/US712869-drawings-page-1.png","B","1902-11-04","Josiah H. Trerise (Butte, Montana)","Miner's pocket-transit",
  "A miner's pocket transit with a transparent cover, a needle lifted off its pivot by a locking lever when not in use, and sighting and level parts for underground surveys.","Plan and section of casing, needle and locking lever"),
P("US303481","86/72/07/5355e638ad6a71/US303481.pdf","60/dc/7c/75bd9800146700/US303481-drawings-page-1.png","B","1884-08-12","Darwin Almy","Odometer",
  "A cheap, simple wagon odometer: a counter clamped to the vehicle and driven by the turning wheel counts the revolutions and shows the distance travelled. Wheel circumference times turns gives distance, for dead-reckoning on land.","Counter train and drive from the wheel"),
P("US163839","db/44/28/5a6603de6437a2/US163839.pdf","cd/b8/66/b3b6b70b2584f5/US163839-drawings-page-1.png","B","1875-06-01","David Baker","Improvement in mariners' compasses (case and gimbal bearings)",
  "A compass box with adjustable gimbal rings, so a compass or chronometer hangs level while a boat or wagon rocks. A gimbal is two pivoted rings at right angles.","Section of the case showing gimbal rings and pivots"),
P("US16727","62/9b/2a/722dd952b55a91/US16727.pdf","d3/c1/13/03c5da20de6385/US16727-drawings-page-1.png","C","1857-03-03","James Fulton (Louisville, Kentucky)","Chronometer-escapement",
  "An improved chronometer escapement, the part that releases the gear train one tick at a time and keeps the balance swinging. Accurate time is what lets you work out longitude, which is why it is here. Precision watchmaking work.","Fig. 1 perspective; Fig. 2 elevation; Fig. 3 section of escapement"),
P("US1279471","32/c2/fa/1dff7cf32b4fdc/US1279471.pdf","74/81/e2/156b42f4b1e798/US1279471-drawings-page-1.png","C","1918-09-17","Elmer A. Sperry (assignor to Sperry Gyroscope Co.)","Gyroscopic compass",
  "Sperry's gyrocompass: a fast-spinning, electrically driven gyroscope settles pointing to true north and is not affected by magnetism or a steel hull. It is a reference for understanding ship and aircraft gyro instruments, not a build project.","Sheet 1: gyro unit, suspension and follow-up mechanism", denoise=True),
P("US399966","28/4f/44/0e303c30936b91/US399966.pdf","9f/8b/45/019535c6345070/US399966-drawings-page-1.png","A","1889-03-19","Robert Jarvie Buchanan","Rotary measuring-wheel",
  "A map measurer for working out distances on maps and charts. A small wheel with a soft rim is rolled along the route. Its side is marked with an outer scale in inches and inner scales in larger units such as miles, and pointers on the axle keep count. Read with 1.1, Reading a topographic map.","Fig. 1 the wheel, frame and handle; Fig. 3 a pointer"),
P("US166477","58/ff/be/38afb83142590f/US166477.pdf","e0/e8/04/7a2275b4f9a42a/US166477-drawings-page-1.png","A","1875-08-10","Thomas Richards","Improvement in life-preserving jackets",
  "A sleeveless cork life jacket: a double vest of strong fabric filled with pieces of cork stitched to a separate lining, and buckled firmly to the body with tongues and buckles. The patent's aim is to float the whole body while leaving the arms free. Read with Part 6, Crossing Water Safely.","Fig. 1 the jacket worn; Fig. 2 section showing the cork pieces"),
P("US435995","fd/b7/1c/8fee4e0db3da9d/US435995.pdf","69/8a/47/fde7094bafade1/US435995-drawings-page-1.png","C","1890-09-09","John Boyd Dunlop","Wheel-tire for cycles",
  "Dunlop's air-filled tire for cycles and other vehicles: an inner rubber tube holding air under pressure, an outer rubber cover thickened where it meets the ground, layers of canvas or linen to resist the pressure, rubber strips to stop the rim cutting the canvas, and a non-return valve through the rim. Dunlop says it absorbs the shock and vibration of rough roads better than the solid rubber tires of the time. Making tires is factory work, so carry spare tubes and a patch kit for a bicycle (see 5.2).","The single figure: section through tire, tube, canvas layers and rim"),
]
